import{_ as t,c as a,o as i,ae as n}from"./chunks/framework.DMK_uHmU.js";const o="/help-center/assets/knowledge-base-manager.C0G6qXHw.png",l="/help-center/assets/knowledge-base-actions.BurZULx5.png",w=JSON.parse('{"title":"Knowledge Base Management Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/AI-Management/Knowledge-Bases/knowledge-base-list.md","filePath":"Administration/AI-Management/Knowledge-Bases/knowledge-base-list.md"}'),s={name:"Administration/AI-Management/Knowledge-Bases/knowledge-base-list.md"};function r(g,e,d,c,h,u){return i(),a("div",null,e[0]||(e[0]=[n('<h1 id="knowledge-base-management-guide" tabindex="-1">Knowledge Base Management Guide <a class="header-anchor" href="#knowledge-base-management-guide" aria-label="Permalink to &quot;Knowledge Base Management Guide&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The Knowledge Base Management system allows administrators to create, manage, and organize collections of information that power the AI Assistant. Knowledge Bases (KBs) contain the content and context that enable the AI to provide accurate, relevant responses to user queries. This guide explains how to effectively use the Knowledge Base Management interface.</p><h2 id="accessing-knowledge-base-management" tabindex="-1">Accessing Knowledge Base Management <a class="header-anchor" href="#accessing-knowledge-base-management" aria-label="Permalink to &quot;Accessing Knowledge Base Management&quot;">​</a></h2><p>The Knowledge Base Management component is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access this component, navigate to <code>/assistant/kb/KBListView</code> in the system. You&#39;ll typically find a link to this page in the administration menu or assistant configuration section.</p><h2 id="knowledge-base-interface-overview" tabindex="-1">Knowledge Base Interface Overview <a class="header-anchor" href="#knowledge-base-interface-overview" aria-label="Permalink to &quot;Knowledge Base Interface Overview&quot;">​</a></h2><p><img src="'+o+'" alt="homepage"></p><p>The Knowledge Base Management interface consists of these key components:</p><ol><li><strong>Header Section</strong>: Contains the title &quot;Knowledge Bases&quot; with a count badge, description, and Add KB button</li><li><strong>Search and Filter Bar</strong>: Tools for finding specific knowledge bases</li><li><strong>Data Table</strong>: Displays knowledge base information in a sortable, filterable table</li><li><strong>Action Buttons</strong>: Quick access to operations like refresh, clear filters, and export</li></ol><h2 id="viewing-knowledge-bases" tabindex="-1">Viewing Knowledge Bases <a class="header-anchor" href="#viewing-knowledge-bases" aria-label="Permalink to &quot;Viewing Knowledge Bases&quot;">​</a></h2><p>The main interface displays all knowledge bases in a tabular format with key information:</p><h3 id="list-view-components" tabindex="-1">List View Components <a class="header-anchor" href="#list-view-components" aria-label="Permalink to &quot;List View Components&quot;">​</a></h3><ol><li><strong>KB Avatar</strong>: Visual representation showing the knowledge base initials in a square tile</li><li><strong>Name/Description</strong>: The primary identifier and explanatory text for each knowledge base</li><li><strong>Groups</strong>: Visual representation of groups with access to this knowledge base</li><li><strong>Topic Tag</strong>: Categorization label for the knowledge base</li><li><strong>Action Buttons</strong>: Quick access to operations specific to each knowledge base</li></ol><h3 id="searching-and-filtering" tabindex="-1">Searching and Filtering <a class="header-anchor" href="#searching-and-filtering" aria-label="Permalink to &quot;Searching and Filtering&quot;">​</a></h3><p>Multiple search and filter options help locate specific knowledge bases:</p><ol><li><strong>Global Search</strong>: Enter text in the search box to filter across name, description, and topic fields</li><li><strong>Group Filter</strong>: Select a specific group to show only knowledge bases accessible to that group</li><li><strong>Topic Filter</strong>: Filter by topic tag to organize knowledge bases by subject matter</li><li><strong>Filter Indicator</strong>: Blue filter button indicates when filters are active</li><li><strong>Clear Filters</strong>: Button to remove all active filters and view the complete list</li></ol><h3 id="sorting-knowledge-bases" tabindex="-1">Sorting Knowledge Bases <a class="header-anchor" href="#sorting-knowledge-bases" aria-label="Permalink to &quot;Sorting Knowledge Bases&quot;">​</a></h3><p>To organize the knowledge base list:</p><ol><li>Click any column header to sort by that field</li><li>Click again to toggle between ascending and descending order</li><li>Click a third time to remove sorting</li></ol><h2 id="managing-knowledge-bases" tabindex="-1">Managing Knowledge Bases <a class="header-anchor" href="#managing-knowledge-bases" aria-label="Permalink to &quot;Managing Knowledge Bases&quot;">​</a></h2><h3 id="creating-a-new-knowledge-base" tabindex="-1">Creating a New Knowledge Base <a class="header-anchor" href="#creating-a-new-knowledge-base" aria-label="Permalink to &quot;Creating a New Knowledge Base&quot;">​</a></h3><p>To create a new knowledge base:</p><ol><li>Click the &quot;Add KB&quot; button in the top-right corner</li><li>The Knowledge Base Dialog will open</li><li>Fill in the required information: <ul><li><strong>Name</strong>: Provide a descriptive name (required)</li><li><strong>Initials</strong>: Two-letter identifier for the avatar (auto-generated but can be changed)</li><li><strong>Description</strong>: Explanation of the knowledge base&#39;s purpose</li><li><strong>Topic Tag</strong>: Optional categorization tag</li></ul></li><li>Click &quot;Save&quot; to create the knowledge base</li></ol><h3 id="editing-knowledge-base-details" tabindex="-1">Editing Knowledge Base Details <a class="header-anchor" href="#editing-knowledge-base-details" aria-label="Permalink to &quot;Editing Knowledge Base Details&quot;">​</a></h3><p>To edit an existing knowledge base:</p><ol><li>Click on the knowledge base name or description in the list</li><li>The Knowledge Base Dialog will open with current settings</li><li>Make necessary changes</li><li>Click &quot;Save&quot; to update the knowledge base</li></ol><h3 id="assigning-groups-to-knowledge-bases" tabindex="-1">Assigning Groups to Knowledge Bases <a class="header-anchor" href="#assigning-groups-to-knowledge-bases" aria-label="Permalink to &quot;Assigning Groups to Knowledge Bases&quot;">​</a></h3><p>Knowledge base access is controlled through group assignments:</p><ol><li>In the Knowledge Base Dialog, locate the Groups section</li><li>Select groups that should have access to this knowledge base</li><li>Users belonging to selected groups will be able to access this knowledge base content</li><li>The table displays assigned groups as avatar circles with group initials</li><li>Hovering over group avatars shows the full group name</li></ol><h3 id="deleting-knowledge-bases" tabindex="-1">Deleting Knowledge Bases <a class="header-anchor" href="#deleting-knowledge-bases" aria-label="Permalink to &quot;Deleting Knowledge Bases&quot;">​</a></h3><p>To delete a knowledge base:</p><ol><li>Click the trash icon in the Actions column</li><li>If the knowledge base contains content: <ul><li>A warning dialog appears indicating the content count</li><li>You must first delete the content or click &quot;Show Content&quot; to view and manage it</li></ul></li><li>If the knowledge base is empty: <ul><li>A confirmation dialog appears</li><li>Click &quot;Delete&quot; to remove the knowledge base</li></ul></li><li>A success notification confirms when deletion is complete</li></ol><h2 id="knowledge-base-related-actions" tabindex="-1">Knowledge Base Related Actions <a class="header-anchor" href="#knowledge-base-related-actions" aria-label="Permalink to &quot;Knowledge Base Related Actions&quot;">​</a></h2><p>Each knowledge base has additional actions accessible via buttons in the Actions column:</p><h3 id="viewing-kb-content" tabindex="-1">Viewing KB Content <a class="header-anchor" href="#viewing-kb-content" aria-label="Permalink to &quot;Viewing KB Content&quot;">​</a></h3><p><img src="'+l+'" alt="homepage"></p><p>To view and manage content within a knowledge base:</p><ol><li>Click the palette icon (first icon in Actions column)</li><li>You&#39;ll be redirected to the Content List View filtered for this knowledge base</li><li>From there you can manage all documents and content items in the knowledge base</li></ol><h3 id="running-test-cases" tabindex="-1">Running Test Cases <a class="header-anchor" href="#running-test-cases" aria-label="Permalink to &quot;Running Test Cases&quot;">​</a></h3><p>To evaluate AI performance with a specific knowledge base:</p><ol><li>Click the gauge icon (second icon in Actions column)</li><li>You&#39;ll be redirected to the Test Case page for this knowledge base</li><li>Create or run tests to evaluate how well the AI handles queries related to this content</li></ol><h3 id="ai-sync-and-embedding" tabindex="-1">AI Sync and Embedding <a class="header-anchor" href="#ai-sync-and-embedding" aria-label="Permalink to &quot;AI Sync and Embedding&quot;">​</a></h3><p>To process and update the AI embeddings for knowledge base content:</p><ol><li>Click the microchip-AI icon (third icon in Actions column)</li><li>You&#39;ll be redirected to the File Queue status page</li><li>Here you can monitor and manage the synchronization of content with the AI system</li><li>This process ensures content is properly vectorized for accurate retrieval</li></ol><h2 id="data-management" tabindex="-1">Data Management <a class="header-anchor" href="#data-management" aria-label="Permalink to &quot;Data Management&quot;">​</a></h2><h3 id="exporting-knowledge-base-data" tabindex="-1">Exporting Knowledge Base Data <a class="header-anchor" href="#exporting-knowledge-base-data" aria-label="Permalink to &quot;Exporting Knowledge Base Data&quot;">​</a></h3><p>To export the knowledge base list to Excel:</p><ol><li>Click the &quot;Export to Excel&quot; button (external link icon in top-right)</li><li>Confirm the export in the dialog that appears</li><li>The browser will download a CSV file</li><li>The export includes all currently visible knowledge bases (respects active filters)</li></ol><h3 id="refreshing-the-knowledge-base-list" tabindex="-1">Refreshing the Knowledge Base List <a class="header-anchor" href="#refreshing-the-knowledge-base-list" aria-label="Permalink to &quot;Refreshing the Knowledge Base List&quot;">​</a></h3><p>To ensure you&#39;re viewing the most current data:</p><ol><li>Click the &quot;Refresh Data&quot; button (refresh icon in top-right)</li><li>The system will reload all knowledge base data from the server</li><li>This is useful after making changes or when multiple administrators are working simultaneously</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Knowledge base list is empty</p><ul><li>Check if filters are active (blue filter button indicates active filters)</li><li>Click the &quot;Clear Filters&quot; button to remove all filters</li><li>Refresh the data using the refresh button</li><li>If still empty, you may need to create your first knowledge base</li></ul><p><strong>Issue</strong>: Cannot delete a knowledge base</p><ul><li>The knowledge base may contain content that must be deleted first</li><li>Follow the prompts to view and manage content before deletion</li><li>Ensure you have proper permissions for deletion</li></ul><p><strong>Issue</strong>: Group avatars not displaying correctly</p><ul><li>The groups store may need refreshing</li><li>Try refreshing the page</li><li>Verify that groups exist in the system</li></ul><p><strong>Issue</strong>: Search not finding expected results</p><ul><li>Check your spelling and try partial terms</li><li>Clear all filters and try a broader search</li><li>Knowledge base names are case-sensitive in some operations</li></ul><p><strong>Issue</strong>: Changes not appearing after edit</p><ul><li>Click the refresh button to reload the latest data</li><li>Check for error messages in toast notifications</li><li>Verify the changes were saved successfully</li></ul><p><strong>Issue</strong>: &quot;Access denied&quot; when trying to access content</p><ul><li>Verify you have permissions for the selected knowledge base</li><li>Check your assigned groups</li><li>Contact your system administrator for access rights</li></ul><hr><p>For additional assistance with knowledge base management, please contact your system administrator.</p>',68)]))}const b=t(s,[["render",r]]);export{w as __pageData,b as default};
